import { useSearchStore } from '../store/searchStore'
import { useBookSearch } from '../hooks/useBookSearch'
import { SearchInput } from '../components/SearchInput'
import { BookGrid } from '../components/BookGrid'
import { LoadMoreButton } from '../components/LoadMoreButton'
import { SortControl } from '../components/SortControl'
import { BookCardSkeleton } from '../components/BookCardSkeleton'
import styles from './SearchPage.module.css'

export default function SearchPage() {
  const query = useSearchStore((s) => s.query)
  const sort = useSearchStore((s) => s.sort)
  const {
    data,
    isLoading,
    isError,
    error,
    isFetchingNextPage,
    hasNextPage,
    fetchNextPage,
  } = useBookSearch(query, sort)

  const docs = data?.pages.flatMap((p) => p.docs) ?? []
  const totalFound = data?.pages[0]?.numFound ?? 0

  return (
    <main className={styles.page}>
      <header className={styles.header}>
        <h1 className={styles.title}>Open Library Explorer</h1>
        <SearchInput />
      </header>

      <section className={styles.results}>
        {isLoading && (
          <div className={styles.skeletonGrid} aria-busy="true">
            {Array.from({ length: 10 }).map((_, i) => (
              <BookCardSkeleton key={i} />
            ))}
          </div>
        )}

        {isError && !data && (
          <p className={styles.error}>
            Something went wrong:{' '}
            {error instanceof Error ? error.message : 'Unknown error'}
          </p>
        )}

        {!isLoading && !isError && data && docs.length === 0 && (
          <p className={styles.status}>
            No books found for &ldquo;{query}&rdquo;
          </p>
        )}

        {docs.length > 0 && (
          <>
            <div className={styles.resultsHeader}>
              <p className={styles.count}>
                Showing {docs.length.toLocaleString()} of {totalFound.toLocaleString()} results
              </p>
              <SortControl />
            </div>
            <BookGrid docs={docs} />

            {isError && data && (
              <p className={styles.error}>
                Failed to load more results. Please try again.
              </p>
            )}

            <LoadMoreButton
              onClick={() => fetchNextPage()}
              isLoading={isFetchingNextPage}
              hasNextPage={hasNextPage}
            />
          </>
        )}

        {!query && !isLoading && (
          <p className={styles.hint}>
            Type a title, author, or topic and press Search.
          </p>
        )}
      </section>
    </main>
  )
}

import { useInfiniteQuery } from '@tanstack/react-query'
import { openLibraryClient } from '../api/client'
import type { SortOption } from '../store/searchStore'

const FIELDS = 'key,title,author_name,author_key,cover_i,first_publish_year,edition_count'
const PAGE_SIZE = 20

export function useBookSearch(query: string, sort: SortOption) {
  return useInfiniteQuery({
    queryKey: ['books', query, sort],
    initialPageParam: 0,
    queryFn: ({ pageParam }) =>
      openLibraryClient.searchBooks({
        queries: {
          q: query,
          fields: FIELDS,
          limit: PAGE_SIZE,
          offset: pageParam,
          sort: sort === 'relevance' ? undefined : sort,
        },
      }),
    getNextPageParam: (lastPage) => {
      const loaded = lastPage.start + lastPage.docs.length
      return loaded < lastPage.numFound ? loaded : undefined
    },
    enabled: query.trim().length > 0,
    staleTime: 1000 * 60 * 5,
  })
}

import { create } from 'zustand'

type SortOption = 'relevance' | 'new' | 'old'

interface SearchState {
  query: string
  sort: SortOption
  setQuery: (query: string) => void
  setSort: (sort: SortOption) => void
}

export const useSearchStore = create<SearchState>((set) => ({
  query: '',
  sort: 'relevance',
  setQuery: (query) => set({ query }),
  setSort: (sort) => set({ sort }),
}))

export type { SortOption }

import { useSearchStore, type SortOption } from '../store/searchStore'
import styles from './SortControl.module.css'

const SORT_OPTIONS: { value: SortOption; label: string }[] = [
  { value: 'relevance', label: 'Relevance' },
  { value: 'new', label: 'Newest first' },
  { value: 'old', label: 'Oldest first' },
]

export function SortControl() {
  const { sort, setSort } = useSearchStore()

  return (
    <div className={styles.wrapper}>
      <label className={styles.label} htmlFor="sort-select">
        Sort:
      </label>
      <select
        id="sort-select"
        className={styles.select}
        value={sort}
        onChange={(e) => setSort(e.target.value as SortOption)}
      >
        {SORT_OPTIONS.map((opt) => (
          <option key={opt.value} value={opt.value}>
            {opt.label}
          </option>
        ))}
      </select>
    </div>
  )
}

import { makeApi, Zodios, type ZodiosOptions } from "@zodios/core";
import { z } from "zod";

const SearchDoc = z
  .object({
    key: z.string(),
    title: z.string(),
    author_name: z.array(z.string()),
    author_key: z.array(z.string()),
    cover_i: z.number().int().nullable(),
    first_publish_year: z.number().int().nullable(),
    edition_count: z.number().int().nullable(),
    subject: z.array(z.string()),
    isbn: z.array(z.string()),
  })
  .partial()
  .passthrough();
const SearchResponse = z
  .object({
    numFound: z.number().int(),
    start: z.number().int(),
    numFoundExact: z.boolean().optional(),
    docs: z.array(SearchDoc),
  })
  .passthrough();
const TextValue = z
  .object({ type: z.string(), value: z.string() })
  .partial()
  .passthrough();
const OLRef = z.object({ key: z.string() }).passthrough();
const Work = z
  .object({
    key: z.string(),
    title: z.string(),
    description: z.union([z.string(), TextValue]).nullable(),
    covers: z.array(z.number().int()).nullable(),
    subjects: z.array(z.string()).nullable(),
    authors: z
      .array(z.object({ author: OLRef, type: OLRef }).partial().passthrough())
      .nullable(),
    first_publish_date: z.string().nullable(),
  })
  .partial()
  .passthrough();
const Author = z
  .object({
    key: z.string(),
    name: z.string(),
    bio: z.union([z.string(), TextValue]).nullable(),
    birth_date: z.string().nullable(),
    death_date: z.string().nullable(),
    photos: z.array(z.number().int()).nullable(),
  })
  .partial()
  .passthrough();
const AuthorWork = z
  .object({
    key: z.string(),
    title: z.string(),
    covers: z.array(z.number().int()).nullable(),
    first_publish_date: z.string().nullable(),
    description: z.union([z.string(), TextValue]).nullable(),
  })
  .partial()
  .passthrough();
const AuthorWorksResponse = z
  .object({
    links: z.object({}).partial().passthrough().nullable(),
    size: z.number().int(),
    entries: z.array(AuthorWork),
  })
  .partial()
  .passthrough();
const SubjectBook = z
  .object({
    key: z.string(),
    title: z.string(),
    authors: z.array(
      z.object({ key: z.string(), name: z.string() }).partial().passthrough()
    ),
    cover_id: z.number().int().nullable(),
    first_publish_year: z.number().int().nullable(),
  })
  .partial()
  .passthrough();
const SubjectResponse = z
  .object({
    key: z.string(),
    name: z.string(),
    work_count: z.number().int(),
    works: z.array(SubjectBook),
  })
  .partial()
  .passthrough();

export const schemas = {
  SearchDoc,
  SearchResponse,
  TextValue,
  OLRef,
  Work,
  Author,
  AuthorWork,
  AuthorWorksResponse,
  SubjectBook,
  SubjectResponse,
};

const endpoints = makeApi([
  {
    method: "get",
    path: "/authors/:authorId",
    alias: "getAuthor",
    requestFormat: "json",
    parameters: [
      {
        name: "authorId",
        type: "Path",
        schema: z.string(),
      },
    ],
    response: Author,
  },
  {
    method: "get",
    path: "/authors/:authorId/works.json",
    alias: "getAuthorWorks",
    requestFormat: "json",
    parameters: [
      {
        name: "authorId",
        type: "Path",
        schema: z.string(),
      },
      {
        name: "limit",
        type: "Query",
        schema: z.number().int().optional().default(50),
      },
      {
        name: "offset",
        type: "Query",
        schema: z.number().int().optional().default(0),
      },
    ],
    response: AuthorWorksResponse,
  },
  {
    method: "get",
    path: "/search.json",
    alias: "searchBooks",
    requestFormat: "json",
    parameters: [
      {
        name: "q",
        type: "Query",
        schema: z.string().optional(),
      },
      {
        name: "title",
        type: "Query",
        schema: z.string().optional(),
      },
      {
        name: "author",
        type: "Query",
        schema: z.string().optional(),
      },
      {
        name: "fields",
        type: "Query",
        schema: z.string().optional(),
      },
      {
        name: "limit",
        type: "Query",
        schema: z.number().int().optional().default(20),
      },
      {
        name: "offset",
        type: "Query",
        schema: z.number().int().optional().default(0),
      },
      {
        name: "sort",
        type: "Query",
        schema: z.enum(["relevance", "new", "old", "random"]).optional(),
      },
    ],
    response: SearchResponse,
  },
  {
    method: "get",
    path: "/subjects/:subject",
    alias: "getSubject",
    requestFormat: "json",
    parameters: [
      {
        name: "subject",
        type: "Path",
        schema: z.string(),
      },
      {
        name: "limit",
        type: "Query",
        schema: z.number().int().optional().default(20),
      },
      {
        name: "offset",
        type: "Query",
        schema: z.number().int().optional().default(0),
      },
    ],
    response: SubjectResponse,
  },
  {
    method: "get",
    path: "/works/:workId",
    alias: "getWork",
    requestFormat: "json",
    parameters: [
      {
        name: "workId",
        type: "Path",
        schema: z.string(),
      },
    ],
    response: Work,
  },
]);

export function createApiClient(baseUrl: string, options?: ZodiosOptions) {
  return new Zodios(baseUrl, endpoints, options);
}

export const openLibraryClient = createApiClient("https://openlibrary.org");

import { test, expect } from '@playwright/test'
import { setupApiMocks } from './helpers/mockApi'

test.beforeEach(async ({ page }) => {
  await setupApiMocks(page)
})

test('sort control hidden with no query', async ({ page }) => {
  await page.goto('/')
  await expect(page.getByLabel('Sort:')).not.toBeVisible()
})

test('sort control visible after search returns results', async ({ page }) => {
  await page.goto('/')
  await page.getByRole('searchbox').fill('tolkien')
  await page.getByRole('button', { name: 'Search' }).click()

  await expect(page.getByRole('list', { name: 'Search results' })).toBeVisible()
  await expect(page.getByLabel('Sort:')).toBeVisible()
})

test('sort control has correct options', async ({ page }) => {
  await page.goto('/')
  await page.getByRole('searchbox').fill('tolkien')
  await page.getByRole('button', { name: 'Search' }).click()
  await expect(page.getByRole('list', { name: 'Search results' })).toBeVisible()

  const select = page.getByLabel('Sort:')
  await expect(select).toBeVisible()
  await expect(select.getByRole('option', { name: 'Relevance' })).toBeAttached()
  await expect(select.getByRole('option', { name: 'Newest first' })).toBeAttached()
  await expect(select.getByRole('option', { name: 'Oldest first' })).toBeAttached()
})

test('changing sort triggers new API request', async ({ page }) => {
  const sortRequests: string[] = []
  page.on('request', (req) => {
    if (req.url().includes('openlibrary.org/search') && req.url().includes('sort=')) {
      sortRequests.push(req.url())
    }
  })

  await page.goto('/')
  await page.getByRole('searchbox').fill('tolkien')
  await page.getByRole('button', { name: 'Search' }).click()
  await expect(page.getByRole('list', { name: 'Search results' })).toBeVisible()

  await page.getByLabel('Sort:').selectOption('new')
  await expect(page.getByRole('list', { name: 'Search results' })).toBeVisible()

  expect(sortRequests.some((url) => url.includes('sort=new'))).toBe(true)
})

import type { Page } from '@playwright/test'
import { readFileSync } from 'fs'
import { join } from 'path'

function loadFixture(name: string) {
  return JSON.parse(readFileSync(join(import.meta.dirname, '../mocks', name), 'utf-8'))
}

type MockOverrides = {
  searchResponse?: object
  workResponse?: object
  authorResponse?: object
  authorWorksResponse?: object
  subjectResponse?: object
  delay?: number
}

export async function setupApiMocks(page: Page, overrides: MockOverrides = {}) {
  const searchTolkien = loadFixture('search-tolkien.json')
  const searchTolkienP2 = loadFixture('search-tolkien-p2.json')
  const searchEmpty = loadFixture('search-empty.json')
  const workHobbit = loadFixture('work-hobbit.json')
  const authorTolkien = loadFixture('author-tolkien.json')
  const authorTolkienWorks = loadFixture('author-tolkien-works.json')
  const subjectFantasy = loadFixture('subject-fantasy.json')

  const fulfillWithDelay = async (route: any, json: object) => {
    if (overrides.delay) {
      await new Promise(f => setTimeout(f, overrides.delay))
    }
    return route.fulfill({ json })
  }

  await page.route('https://openlibrary.org/search.json**', (route) => {
    const url = new URL(route.request().url())
    const q = url.searchParams.get('q') ?? ''
    const offset = Number(url.searchParams.get('offset') ?? 0)

    let body = searchTolkien
    if (overrides.searchResponse) body = overrides.searchResponse
    else if (q.toLowerCase().includes('zzznoresults')) body = searchEmpty
    else if (offset > 0) body = searchTolkienP2

    return fulfillWithDelay(route, body)
  })

  await page.route('https://openlibrary.org/subjects/**', (route) => {
    return fulfillWithDelay(route, overrides.subjectResponse ?? subjectFantasy)
  })

  await page.route('https://openlibrary.org/works/**', (route) => {
    return fulfillWithDelay(route, overrides.workResponse ?? workHobbit)
  })

  await page.route('https://openlibrary.org/authors/**', (route) => {
    if (route.request().url().includes('/works.json')) {
      return fulfillWithDelay(route, overrides.authorWorksResponse ?? authorTolkienWorks)
    }
    return fulfillWithDelay(route, overrides.authorResponse ?? authorTolkien)
  })

  // Block cover images to speed up tests
  await page.route('https://covers.openlibrary.org/**', (route) => {
    return route.abort()
  })
}

