import { useMemo } from 'react'
import { useSearchStore } from '../store/searchStore'
import { useBookSearch } from '../hooks/useBookSearch'
import { SearchInput } from '../components/SearchInput'
import { BookGrid } from '../components/BookGrid'
import { LoadMoreButton } from '../components/LoadMoreButton'
import { SortControl } from '../components/SortControl'
import { AuthorFilter } from '../components/AuthorFilter'
import { BookCardSkeleton } from '../components/BookCardSkeleton'
import styles from './SearchPage.module.css'

export default function SearchPage() {
  const query = useSearchStore((s) => s.query)
  const sort = useSearchStore((s) => s.sort)
  const author = useSearchStore((s) => s.author)
  const {
    data,
    isLoading,
    isError,
    error,
    isFetchingNextPage,
    hasNextPage,
    fetchNextPage,
  } = useBookSearch(query, sort, author)

  const docs = useMemo(
    () => data?.pages.flatMap((p) => p.docs) ?? [],
    [data]
  )
  const visibleDocs = useMemo(
    () =>
      author
        ? docs.filter((doc) => doc.author_name?.includes(author))
        : docs,
    [docs, author]
  )
  const authors = useMemo(() => {
    const names = new Set<string>()
    for (const doc of docs) {
      for (const name of doc.author_name ?? []) {
        if (name) names.add(name)
      }
    }
    // Keep the active author selectable even if the latest page no longer
    // contains a book by them.
    if (author) names.add(author)
    return Array.from(names).sort((a, b) => a.localeCompare(b))
  }, [docs, author])
  const totalFound = data?.pages[0]?.numFound ?? 0

  return (
    <main className={styles.page}>
      <header className={styles.header}>
        <h1 className={styles.title}>Open Library Explorer</h1>
        <SearchInput />
      </header>

      <section className={styles.results}>
        {isLoading && (
          <div className={styles.skeletonGrid} aria-busy="true">
            {Array.from({ length: 10 }).map((_, i) => (
              <BookCardSkeleton key={i} />
            ))}
          </div>
        )}

        {isError && !data && (
          <p className={styles.error}>
            Something went wrong:{' '}
            {error instanceof Error ? error.message : 'Unknown error'}
          </p>
        )}

        {!isLoading && !isError && data && visibleDocs.length === 0 && (
          <p className={styles.status}>
            No books found for &ldquo;{query}&rdquo;
          </p>
        )}

        {(docs.length > 0 || author) && (
          <div className={styles.resultsHeader}>
            <p className={styles.count}>
              Showing {visibleDocs.length.toLocaleString()} of{' '}
              {totalFound.toLocaleString()} results
            </p>
            <div className={styles.filters}>
              <AuthorFilter authors={authors} />
              {docs.length > 0 && <SortControl />}
            </div>
          </div>
        )}

        {visibleDocs.length > 0 && (
          <>
            <BookGrid docs={visibleDocs} />

            {isError && data && (
              <p className={styles.error}>
                Failed to load more results. Please try again.
              </p>
            )}

            <LoadMoreButton
              onClick={() => fetchNextPage()}
              isLoading={isFetchingNextPage}
              hasNextPage={hasNextPage}
            />
          </>
        )}

        {!query && !isLoading && (
          <p className={styles.hint}>
            Type a title, author, or topic and press Search.
          </p>
        )}
      </section>
    </main>
  )
}
